package com.teamflow.planning.repository;
import com.teamflow.planning.api.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
import java.time.*; import java.util.*;
@Repository public class PlanningRepository {
 private final JdbcTemplate jdbc; public PlanningRepository(JdbcTemplate j){jdbc=j;}
 public AllocationResponse saveAllocation(UUID org,AllocationRequest r){UUID id=UUID.randomUUID();var now=OffsetDateTime.now(ZoneOffset.UTC);jdbc.update("INSERT INTO allocations VALUES (?,?,?,?,?,?,?,?,?,?,?)",id,org,r.projectId(),r.resourceType(),r.resourceId(),r.startDate(),r.endDate(),r.fixed()!=null&&r.fixed(),"CONFIRMED",now,now);return new AllocationResponse(id,org,r.projectId(),r.resourceType(),r.resourceId(),r.startDate(),r.endDate(),r.fixed()!=null&&r.fixed(),"CONFIRMED",now,now);}
 public List<AllocationResponse> allocations(UUID org,UUID project,String type,UUID resource,LocalDate from,LocalDate to){StringBuilder q=new StringBuilder("SELECT * FROM allocations WHERE organization_id=?");List<Object> p=new ArrayList<>(List.of(org));if(project!=null){q.append(" AND project_id=?");p.add(project);}if(type!=null){q.append(" AND resource_type=?");p.add(type);}if(resource!=null){q.append(" AND resource_id=?");p.add(resource);}if(from!=null){q.append(" AND end_date>=?");p.add(from);}if(to!=null){q.append(" AND start_date<=?");p.add(to);}q.append(" ORDER BY start_date");return jdbc.query(q.toString(),(rs,n)->new AllocationResponse(rs.getObject("id",UUID.class),rs.getObject("organization_id",UUID.class),rs.getObject("project_id",UUID.class),rs.getString("resource_type"),rs.getObject("resource_id",UUID.class),rs.getObject("start_date",LocalDate.class),rs.getObject("end_date",LocalDate.class),rs.getBoolean("fixed"),rs.getString("status"),rs.getObject("created_at",OffsetDateTime.class),rs.getObject("updated_at",OffsetDateTime.class)),p.toArray());}
 public void setFixed(UUID org,UUID id,boolean fixed){jdbc.update("UPDATE allocations SET fixed=?,updated_at=? WHERE organization_id=? AND id=?",fixed,OffsetDateTime.now(ZoneOffset.UTC),org,id);}
 public void cancel(UUID org,UUID id){jdbc.update("UPDATE allocations SET status='CANCELLED',updated_at=? WHERE organization_id=? AND id=?",OffsetDateTime.now(ZoneOffset.UTC),org,id);}
 public TransportResponse saveTransport(UUID org,TransportRequest r){UUID id=UUID.randomUUID();var now=OffsetDateTime.now(ZoneOffset.UTC);LocalDate arrival=r.durationDays()==null?null:r.startDate().plusDays(r.durationDays());String status=r.durationDays()==null?"PENDING":"CONFIRMED";jdbc.update("INSERT INTO transports VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",id,org,r.resourceType(),r.resourceId(),r.origin(),r.destination(),r.startDate(),r.durationDays(),arrival,status,now,now);return new TransportResponse(id,org,r.resourceType(),r.resourceId(),r.origin(),r.destination(),r.startDate(),r.durationDays(),arrival,status,now,now);}
 public List<TransportResponse> transports(UUID org){return jdbc.query("SELECT * FROM transports WHERE organization_id=? ORDER BY start_date",(rs,n)->new TransportResponse(rs.getObject("id",UUID.class),rs.getObject("organization_id",UUID.class),rs.getString("resource_type"),rs.getObject("resource_id",UUID.class),rs.getString("origin"),rs.getString("destination"),rs.getObject("start_date",LocalDate.class),(Integer)rs.getObject("duration_days"),rs.getObject("arrival_date",LocalDate.class),rs.getString("status"),rs.getObject("created_at",OffsetDateTime.class),rs.getObject("updated_at",OffsetDateTime.class)),org);}
 public ProposalResponse proposal(UUID org,String payload){UUID id=UUID.randomUUID();var now=OffsetDateTime.now(ZoneOffset.UTC);Long version=jdbc.queryForObject("SELECT COALESCE(MAX(version),0)+1 FROM planning_proposals WHERE organization_id=?",Long.class,org);jdbc.update("INSERT INTO planning_proposals VALUES (?,?,?,?,?::jsonb,?)",id,org,version,"DRAFT",payload,now);return new ProposalResponse(id,org,version,"DRAFT","Proposta heurística determinística; requer revisão e aprovação.",now);}
 public void approve(UUID org,UUID id){jdbc.update("UPDATE planning_proposals SET status='APPROVED',approved_at=? WHERE organization_id=? AND id=? AND status='DRAFT'",OffsetDateTime.now(ZoneOffset.UTC),org,id);}
}
